//! The event envelope and the strict payload types (system design §5.3).
//!
//! Payload structs carry exactly the fields the contract allows — there is no
//! free-form map anywhere — so content cannot be smuggled into an event by accident.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// One event as sent to `POST /v1/ingestion/event-batches`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Envelope {
    /// UUIDv4 generated by the agent; the idempotency key.
    pub event_id: Uuid,
    /// Organization the device belongs to.
    pub organization_id: String,
    /// The enrolled device.
    pub device_id: String,
    /// The work session the event belongs to (agent-generated UUID).
    pub session_id: Uuid,
    /// Organization policy revision the agent was applying (0 = none received yet).
    pub policy_version: i64,
    /// `event_type` + `payload`.
    #[serde(flatten)]
    pub body: EventBody,
    /// When the event happened (device wall clock, UTC).
    #[serde(with = "crate::ts")]
    pub occurred_at: DateTime<Utc>,
    /// Per-device, strictly increasing, survives restarts.
    pub sequence: u64,
    /// Milliseconds since session start on the monotonic clock.
    pub monotonic_ms: u64,
}

/// The typed `event_type` / `payload` pair.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "event_type", content = "payload")]
pub enum EventBody {
    /// `session.started.v1`
    #[serde(rename = "session.started.v1")]
    SessionStarted(SessionStarted),
    /// `session.paused.v1`
    #[serde(rename = "session.paused.v1")]
    SessionPaused(SessionPaused),
    /// `session.resumed.v1`
    #[serde(rename = "session.resumed.v1")]
    SessionResumed(Empty),
    /// `session.stopped.v1`
    #[serde(rename = "session.stopped.v1")]
    SessionStopped(SessionStopped),
    /// `activity_bucket.v1`
    #[serde(rename = "activity_bucket.v1")]
    ActivityBucket(ActivityBucket),
    /// `app_usage.v1`
    #[serde(rename = "app_usage.v1")]
    AppUsage(AppUsage),
    /// `data_gap.v1`
    #[serde(rename = "data_gap.v1")]
    DataGap(DataGap),
}

/// Whether an event may be dropped when the outbox is over its storage cap.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Retention {
    /// Session lifecycle and data-gap events: never dropped.
    Protected,
    /// Activity buckets and app usage: oldest are dropped first when over cap.
    Droppable,
}

impl EventBody {
    /// The wire `event_type` string.
    pub fn event_type(&self) -> &'static str {
        match self {
            EventBody::SessionStarted(_) => "session.started.v1",
            EventBody::SessionPaused(_) => "session.paused.v1",
            EventBody::SessionResumed(_) => "session.resumed.v1",
            EventBody::SessionStopped(_) => "session.stopped.v1",
            EventBody::ActivityBucket(_) => "activity_bucket.v1",
            EventBody::AppUsage(_) => "app_usage.v1",
            EventBody::DataGap(_) => "data_gap.v1",
        }
    }

    /// Storage-cap class of the event.
    pub fn retention(&self) -> Retention {
        match self {
            EventBody::ActivityBucket(_) | EventBody::AppUsage(_) => Retention::Droppable,
            _ => Retention::Protected,
        }
    }

    /// `true` for `session.*` events.
    pub fn is_lifecycle(&self) -> bool {
        matches!(
            self,
            EventBody::SessionStarted(_)
                | EventBody::SessionPaused(_)
                | EventBody::SessionResumed(_)
                | EventBody::SessionStopped(_)
        )
    }
}

/// An empty JSON object payload (`{}`).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Empty {}

/// `session.started.v1` payload.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SessionStarted {
    /// Project the session is booked to, if any. Omitted when absent.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub project_id: Option<String>,
    /// Task the session is booked to, if any. Omitted when absent.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub task_id: Option<String>,
}

/// Why a session was paused.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PauseReason {
    /// The employee paused.
    User,
    /// Automatic pause after inactivity (reserved; not triggered by this agent).
    IdleAuto,
    /// The policy's work-hours window ended.
    WorkHours,
}

/// `session.paused.v1` payload.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SessionPaused {
    /// Why the session was paused.
    pub reason: PauseReason,
}

/// Why a session was stopped.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum StopReason {
    /// The employee stopped.
    User,
    /// OS logout.
    Logout,
    /// OS shutdown or agent shutdown / crash recovery.
    Shutdown,
    /// The device credential was revoked (never sent; the server already knows).
    Revoked,
    /// Policy forced the stop.
    Policy,
    /// The server rejected the session start as overlapping another session.
    Overlap,
}

/// `session.stopped.v1` payload.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SessionStopped {
    /// Why the session was stopped.
    pub reason: StopReason,
}

/// Quality of the input data behind an activity bucket.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DataQuality {
    /// Every sampled second had full input data.
    Ok,
    /// Some seconds were degraded (e.g. counts unavailable) or missing.
    Partial,
    /// No input data was available for any second of the bucket.
    PermissionMissing,
}

/// `activity_bucket.v1` payload. Invariant: `active_seconds + idle_seconds <= 60`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ActivityBucket {
    /// Start of the UTC minute the bucket covers (seconds and sub-seconds are zero).
    #[serde(with = "crate::ts")]
    pub bucket_start: DateTime<Utc>,
    /// Seconds with input (or within the idle threshold of input).
    pub active_seconds: u32,
    /// Seconds belonging to an idle run longer than the threshold.
    pub idle_seconds: u32,
    /// Number of key presses — a count only, never which keys.
    pub keyboard_count: u64,
    /// Number of mouse events (moves, clicks, wheel) — a count only.
    pub mouse_count: u64,
    /// Data quality of the bucket.
    pub data_quality: DataQuality,
}

/// `app_usage.v1` payload.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AppUsage {
    /// Stable application identifier (bundle id / executable name).
    pub app_identifier: String,
    /// Human-readable application name.
    pub app_name: String,
    /// Registrable domain (never a URL). This agent never collects it; always omitted.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub domain: Option<String>,
    /// When the segment started.
    #[serde(with = "crate::ts")]
    pub started_at: DateTime<Utc>,
    /// Foreground duration in seconds, `1..=3600`.
    pub duration_seconds: u32,
}

/// Why there is no data for a span of a session.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum GapReason {
    /// The machine was asleep / hibernating.
    Suspended,
    /// The agent was not running (crash, kill) while a session was open.
    OfflineAgentStopped,
    /// OS permissions were missing.
    PermissionMissing,
    /// The wall clock was changed.
    ClockChange,
}

/// `data_gap.v1` payload.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DataGap {
    /// Start of the gap.
    #[serde(with = "crate::ts")]
    pub gap_start: DateTime<Utc>,
    /// End of the gap (`>= gap_start`).
    #[serde(with = "crate::ts")]
    pub gap_end: DateTime<Utc>,
    /// Why there is no data.
    pub reason: GapReason,
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::TimeZone;
    use serde_json::json;

    fn envelope(body: EventBody) -> Envelope {
        Envelope {
            event_id: Uuid::nil(),
            organization_id: "org".into(),
            device_id: "dev".into(),
            session_id: Uuid::nil(),
            policy_version: 12,
            body,
            occurred_at: Utc.with_ymd_and_hms(2026, 10, 28, 9, 41, 0).unwrap(),
            sequence: 1842,
            monotonic_ms: 5_523_000,
        }
    }

    #[test]
    fn envelope_matches_wire_shape() {
        let e = envelope(EventBody::ActivityBucket(ActivityBucket {
            bucket_start: Utc.with_ymd_and_hms(2026, 10, 28, 9, 41, 0).unwrap(),
            active_seconds: 42,
            idle_seconds: 18,
            keyboard_count: 120,
            mouse_count: 300,
            data_quality: DataQuality::Ok,
        }));
        let v = serde_json::to_value(&e).unwrap();
        assert_eq!(
            v,
            json!({
                "event_id": "00000000-0000-0000-0000-000000000000",
                "organization_id": "org",
                "device_id": "dev",
                "session_id": "00000000-0000-0000-0000-000000000000",
                "policy_version": 12,
                "event_type": "activity_bucket.v1",
                "occurred_at": "2026-10-28T09:41:00Z",
                "sequence": 1842,
                "monotonic_ms": 5523000,
                "payload": {
                    "bucket_start": "2026-10-28T09:41:00Z",
                    "active_seconds": 42,
                    "idle_seconds": 18,
                    "keyboard_count": 120,
                    "mouse_count": 300,
                    "data_quality": "ok"
                }
            })
        );
        let back: Envelope = serde_json::from_value(v).unwrap();
        assert_eq!(back, e);
    }

    #[test]
    fn optional_fields_are_omitted_and_empty_payload_is_object() {
        let v = serde_json::to_value(envelope(EventBody::SessionStarted(SessionStarted::default())))
            .unwrap();
        assert_eq!(v["payload"], json!({}));
        let v = serde_json::to_value(envelope(EventBody::SessionResumed(Empty {}))).unwrap();
        assert_eq!(v["payload"], json!({}));
        assert_eq!(v["event_type"], "session.resumed.v1");
        let v = serde_json::to_value(envelope(EventBody::SessionStopped(SessionStopped {
            reason: StopReason::Overlap,
        })))
        .unwrap();
        assert_eq!(v["payload"], json!({"reason": "overlap"}));
        let v = serde_json::to_value(envelope(EventBody::DataGap(DataGap {
            gap_start: Utc.with_ymd_and_hms(2026, 10, 28, 9, 0, 0).unwrap(),
            gap_end: Utc.with_ymd_and_hms(2026, 10, 28, 11, 0, 0).unwrap(),
            reason: GapReason::OfflineAgentStopped,
        })))
        .unwrap();
        assert_eq!(v["payload"]["reason"], "offline_agent_stopped");
        let v = serde_json::to_value(envelope(EventBody::AppUsage(AppUsage {
            app_identifier: "com.example.editor".into(),
            app_name: "Editor".into(),
            domain: None,
            started_at: Utc.with_ymd_and_hms(2026, 10, 28, 9, 0, 0).unwrap(),
            duration_seconds: 300,
        })))
        .unwrap();
        assert!(v["payload"].get("domain").is_none());
    }

    #[test]
    fn event_type_strings_match_serde() {
        let bodies = [
            EventBody::SessionStarted(SessionStarted::default()),
            EventBody::SessionPaused(SessionPaused {
                reason: PauseReason::WorkHours,
            }),
            EventBody::SessionResumed(Empty {}),
            EventBody::SessionStopped(SessionStopped {
                reason: StopReason::User,
            }),
        ];
        for b in bodies {
            let v = serde_json::to_value(envelope(b.clone())).unwrap();
            assert_eq!(v["event_type"], b.event_type());
            assert!(b.is_lifecycle());
            assert_eq!(b.retention(), Retention::Protected);
        }
    }
}
